INSERT INTO "public"."products" ("id", "name", "description", "category", "base_price", "discount_price", "discount_start_date", "discount_end_date", "discount_active", "purity_percentage", "molecular_weight", "cas_number", "sequence", "storage_conditions", "inclusions", "stock_quantity", "available", "featured", "image_url", "safety_sheet_url", "created_at", "updated_at") VALUES ('0d656a9b-9179-4202-86b9-5901c007e43f', 'Lemon Bottle Promax 50ml (China)', 'Lemon Bottle is a peptide product marketed for fat loss, detox, and metabolism support that typically combines amino acids and lipotropic nutrients designed to help improve fat breakdown, energy use, and liver function. It may support enhanced metabolism, improved energy levels, and better fat mobilization when paired with a healthy diet and exercise.', 'all', '1400.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 3, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781293594629-9pdgo9p7yof.jpeg', null, '2026-06-10 11:14:30.535407+00', '2026-06-10 11:14:30.535407+00'), ('108dad5b-b84f-4fd3-babb-0fb2314dab31', 'TESAMORELIN 10mg', 'Tesamorelin is a synthetic peptide analog of growth hormone-releasing hormone (GHRH) that stimulates the pituitary gland to produce growth hormone (GH). It is primarily used in clinical settings to reduce visceral fat in people with conditions like HIV-associated lipodystrophy and to support body composition improvements. By boosting GH levels, Tesamorelin may also enhance metabolism, lean muscle maintenance, and tissue repair.', 'c0a80121-0002-4e78-94f8-585d77059002', '2200.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 0, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780998352212-ywwhl0gd1.png', null, '2026-06-09 09:43:28.134582+00', '2026-06-09 09:43:28.134582+00'), ('110dce81-b74b-4c93-99b5-67a4e3dd0ae1', 'GLOW 70', 'Glow is a research peptide blend designed to support skin health, repair, and rejuvenation at the cellular level. It combines GHK-Cu, which stimulates collagen and elastin production for improved skin texture and firmness, with BPC‑157 and TB‑500, which promote tissue repair, reduce inflammation, and support overall cellular regeneration. Together, this combination aims to enhance skin radiance, improve elasticity, and accelerate recovery from minor tissue damage.', 'c0a80121-0003-4e78-94f8-585d77059003', '2300.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 3, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994702639-c3x63x7j2z4.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('23329f6f-532e-4341-b27c-dae8cbae5886', 'Tirzepatide 60mg', 'Tirzepatide 60mg', 'c0a80121-0002-4e78-94f8-585d77059002', '2300.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 10, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780998698330-01aw0kcapn71.png', null, '2026-06-09 09:39:55.809444+00', '2026-06-09 09:39:55.809444+00'), ('2373acaa-473a-4eec-98fc-267ea854e5a5', 'FAT BLASTER', 'Fat Blaster blend', 'c0a80121-0002-4e78-94f8-585d77059002', '1700.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 100, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995242341-ezgfia7mwur.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('2d146237-fb7d-40e2-bb37-522bbc1fe5f8', 'SS-31 50mg', 'SS‑31 (also called Elamipretide) is a synthetic peptide that targets mitochondria, the energy-producing structures in cells, to improve their function and reduce oxidative stress. It helps stabilize mitochondrial membranes, enhance energy production, and protect cells from damage caused by reactive oxygen species. SS‑31 is being researched for potential benefits in age-related diseases, metabolic disorders, cardiovascular health, and muscle function, as it may improve cellular resilience and organ performance.', 'c0a80121-0004-4e78-94f8-585d77059004', '2950.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 0, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780998728693-tlwr23a5oj.png', null, '2026-06-09 09:40:39.688615+00', '2026-06-09 09:40:39.688615+00'), ('2f9f48a0-ebed-4aa0-affa-2fce38a5f0c5', 'Glutathione Fuan 1500', 'Glutathione is a powerful antioxidant naturally produced in the body that helps protect cells from oxidative stress and free radical damage. It plays a key role in detoxification, supporting the liver in removing toxins, heavy metals, and waste products. Glutathione also helps maintain skin health and brightness by inhibiting melanin production, supports immune system function, and contributes to overall cellular repair and longevity.

', 'c0a80121-0003-4e78-94f8-585d77059003', '1650.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 29, true, true, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995567325-5zzjtypqhtv.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('35259ac9-337d-4921-ac5f-d53b55759ed9', '5 AMINO 1MQ', '5‑Amino (5‑Amino‑1MQ) is a research compound that supports metabolic health by inhibiting NNMT, enhancing cellular energy use, promoting fat metabolism, improving insulin sensitivity, and supporting healthy glucose regulation. It may also help reduce fat accumulation, increase energy expenditure, and maintain overall metabolic balance, making it of interest in studies on obesity and metabolic syndrome.', 'c0a80121-0002-4e78-94f8-585d77059002', '1600.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 0, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994990095-om5f1gsaim.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('39558e04-e920-4190-a06a-3eee0dbc9033', 'RETA 20', 'Retatrutide is an investigational triple‑receptor agonist peptide drug that activates GLP‑1, GIP, and glucagon receptors all at once to regulate metabolism, suppress appetite, improve insulin sensitivity, and increase energy expenditure. In clinical research, it has shown significant weight loss results (often more than earlier GLP‑1 drugs) and improvements in blood sugar control and fat metabolism, making it a promising therapy for obesity and metabolic disorders like type 2 diabetes.', 'c0a80121-0002-4e78-94f8-585d77059002', '1800.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 3, true, true, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994853176-da9fgsnl0jd.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('3975c1da-bb1e-44e3-bd70-1e54eee9882a', 'ACNE REMOVAL SKIN BOOSTER', 'Acne Removal Skin Booster is a skincare treatment designed to help reduce acne breakouts, control excess oil, and promote clearer-looking skin. It typically contains ingredients that help unclog pores, calm inflammation, and support skin healing while minimizing the appearance of acne marks. With regular use, it may help improve overall skin texture, balance oil production, and maintain a healthier complexion.', 'all', '750.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 2, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781293140778-0crw3tmnbts7.png', null, '2026-06-10 12:29:04.662187+00', '2026-06-10 12:29:04.662187+00'), ('3cd3e4ba-a355-48c4-9720-64bd4d1abc50', 'Glutathione GlutaOne Korea', 'GlutatOne is commonly used for its antioxidant properties, helping protect cells from oxidative stress and supporting overall wellness. It may also support liver function, immune health, and promote a brighter, more even-looking skin tone by helping reduce the appearance of pigmentation.

', 'c0a80121-0003-4e78-94f8-585d77059003', '1650.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 47, true, true, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780996266149-9l7k0mv2n.jpeg', null, '2026-06-09 09:01:20.227219+00', '2026-06-09 09:01:20.227219+00'), ('3d653f9c-afa0-4850-8e76-fcb659fc1644', 'PDRN - SKIN BOOSTER SERUM', 'PDRN (Polydeoxyribonucleotide) Skin Booster Serum is a skincare product that uses purified DNA fragments—commonly derived from salmon DNA—to help support skin repair, hydration, and collagen production. It is often used to improve skin texture, elasticity, radiance, and the appearance of fine lines while helping calm inflammation and strengthen the skin barrier', 'all', '750.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 0, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781293175354-n35pmolnlfc.png', null, '2026-06-10 12:25:04.598705+00', '2026-06-10 12:25:04.598705+00'), ('3ff7f74f-0f3f-4c62-9fba-6ddcf63b9b29', 'SELANK 10', 'Selank is a synthetic peptide developed from the naturally occurring tetrapeptide tuftsin, studied for its anxiolytic, cognitive, and mood-enhancing effects. It may help reduce anxiety and stress, improve mental clarity, focus, and memory, and support immune system regulation.', 'c0a80121-0004-4e78-94f8-585d77059004', '1600.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 5, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995449545-4ldhvemuo16.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('4135e3cf-16a1-4a15-b1e2-a1521834c901', 'LIPO C B12', 'Lipo-C with B12 is a lipotropic injection that helps support fat metabolism by assisting the body in breaking down and transporting fats more efficiently. It typically contains compounds like methionine, inositol, and choline, which work together to support liver function and reduce fat accumulation. The added vitamin B12 helps boost energy levels, improve metabolism, and reduce fatigue, especially in people with low B12 levels. Overall, it’s commonly used to support weight management, energy, and overall metabolic health.

', 'c0a80121-0002-4e78-94f8-585d77059002', '1600.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 5, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995333285-i2i7z88q3we.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('48f3fb91-370d-4177-8baf-c423dce43892', 'CAGRI 5', 'Cagrilintide is an experimental injectable peptide designed to support weight loss and metabolic health. It mimics the hormone amylin, which works alongside insulin to regulate appetite, slow stomach emptying, and reduce post-meal blood sugar spikes. By suppressing appetite and promoting satiety, it helps reduce calorie intake and can contribute to fat loss.', 'c0a80121-0002-4e78-94f8-585d77059002', '1500.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 10, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995126099-xxp90s80rdg.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('6c26b97e-57ce-4b7c-8157-8d0073ff54a8', 'NAD+ 500', 'NAD⁺ (Nicotinamide Adenine Dinucleotide) is a vital coenzyme found in every cell that plays a central role in energy production, DNA repair, and cellular metabolism. It helps mitochondria convert nutrients into energy, supports healthy aging, enhances cellular repair, and may improve cognitive function, metabolism, and longevity. NAD⁺ levels naturally decline with age, which is linked to reduced energy, slower recovery, and age-related cellular stress. Supplements or IV therapies that boost NAD⁺ aim to restore these levels, supporting energy, vitality, and overall cellular health.', 'c0a80121-0004-4e78-94f8-585d77059004', '1600.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 8, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995415531-c19zi9btshc.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('705fc63c-45bd-4490-8287-ada503789fd9', 'MOTSC 10', 'MOTS‑C is a naturally occurring mitochondrial-derived peptide that plays a key role in cellular energy regulation and metabolism. It helps improve insulin sensitivity, glucose utilization, and fat metabolism, supporting metabolic health and potentially aiding in weight management. MOTS‑C also promotes mitochondrial function, helping cells produce energy more efficiently, and may have anti-inflammatory and longevity-supporting effects.', 'c0a80121-0004-4e78-94f8-585d77059004', '1300.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 5, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995367696-ufoavqi2rr.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('7d90d038-6f96-430a-8f67-8a90e5b0d1ef', 'Tirzepatide 15', 'Tirzepatide is a prescription medication that mimics two natural hormones, GLP-1 and GIP, to help regulate blood sugar and appetite. It works by stimulating insulin release when blood sugar is high, slowing digestion, and reducing appetite, which often leads to significant weight loss. It is primarily used for type 2 diabetes management and obesity treatment and may also improve heart health by lowering cardiovascular risk factors.', 'c0a80121-0002-4e78-94f8-585d77059002', '1500.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 10, true, true, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994459155-06t3nqy6h53t.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('84da4600-05cc-4e0e-92b5-e2e8c372c04b', 'AOD 5', 'AOD-9604 is a synthetic peptide fragment derived from human growth hormone (HGH), designed specifically to target fat metabolism without affecting blood sugar or growth pathways. It works by stimulating lipolysis (fat breakdown) and inhibiting lipogenesis (fat storage), which is why it’s marketed for fat loss and weight management. Unlike full HGH, it does not appear to significantly impact insulin levels or cause tissue growth. It has been studied for obesity treatment, but it is not FDA-approved for weight loss and is often sold as a research peptide.', 'c0a80121-0002-4e78-94f8-585d77059002', '1600.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 2, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995050501-a66xc8z4s5.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('9d5bec1f-e254-4ced-95d1-9c85484f6ac4', 'Tirzepatide 30', 'Tirzepatide is a prescription medication that mimics two natural hormones, GLP-1 and GIP, to help regulate blood sugar and appetite. It works by stimulating insulin release when blood sugar is high, slowing digestion, and reducing appetite, which often leads to significant weight loss. It is primarily used for type 2 diabetes management and obesity treatment and may also improve heart health by lowering cardiovascular risk factors.', 'c0a80121-0002-4e78-94f8-585d77059002', '1900.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 14, true, true, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994496586-yhlp83fiv.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('9da6735d-1622-4348-a25b-3de0fedb5e1c', 'LCARNITINE 600', 'L-Carnitine helps your body convert stored fat into energy by transporting fatty acids into the mitochondria, making it useful for fat metabolism and energy production. It may improve exercise performance and endurance, especially during cardio or fat-loss phases. Many users also report reduced fatigue and faster recovery after workouts. Additionally, it can support brain function and heart health due to its role in cellular energy support.

', 'c0a80121-0002-4e78-94f8-585d77059002', '1500.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 4, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780995277914-viz8yxhedb8.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('b01d07c2-8c99-4c94-b4d9-99f340f863ee', 'SPOT FADING SKIN BOOSTER', 'Spot Fading Skin Booster is a skincare treatment formulated to help reduce the appearance of dark spots, post-acne marks, sun damage, and uneven skin tone. It typically contains brightening and skin-renewing ingredients that support a more radiant and uniform complexion. With consistent use, it may help fade discoloration over time while improving overall skin clarity and glow.', 'all', '750.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 4, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781293246640-9jf08x6690b.png', null, '2026-06-10 12:30:11.542564+00', '2026-06-10 12:30:11.542564+00'), ('b0535035-3a16-44d7-bf6f-1625ec13b69d', 'Lemon Bottle 10ml (Vietnam)', 'Lemon Bottle 10ML Vietname an aesthetic solution commonly used in beauty and contouring treatments to support the appearance of slimmer, more defined areas. It is popular for its blend of ingredients that may help target stubborn fat areas while supporting smoother-looking skin. Many users choose it for non-surgical body contouring routines focused on areas like the chin, arms, abdomen, and thighs.', 'c0a80121-0002-4e78-94f8-585d77059002', '900.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 0, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781292926690-43yl5kjp4lm.jpeg', null, '2026-06-10 11:17:16.157615+00', '2026-06-10 11:17:16.157615+00'), ('b2f33c5c-2f29-4d72-92c2-c2e35989cf58', 'SEMAX 10', 'Semax is a synthetic peptide derived from a fragment of adrenocorticotropic hormone (ACTH), primarily studied for its neuroprotective, cognitive, and mood-enhancing effects. It may help improve memory, focus, learning, and mental clarity, reduce anxiety and stress, and support brain health by enhancing blood flow and neurotrophic factor activity. Semax is also researched for its potential to protect neurons from oxidative stress and promote recovery after brain injury.', 'c0a80121-0004-4e78-94f8-585d77059004', '1500.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 2, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994637713-zqchter9wf.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('ba16ac1b-ffc3-497c-ab87-31ba65c510f6', 'KPV 10mg', 'KPV is a small peptide fragment derived from the α‑melanocyte-stimulating hormone (α‑MSH) that is studied for its anti-inflammatory and immune-modulating properties. It may help reduce inflammation, support wound healing, protect tissues from oxidative stress, and promote gut health. KPV is often included in research peptide blends for its ability to enhance tissue repair, recovery, and cellular protection.

', 'c0a80121-0004-4e78-94f8-585d77059004', '1500.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 14, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994591905-na25olmql6.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('bcb4672a-fde8-40cb-9e21-d42d5ee150c2', 'GHKCU 100', 'GHK-Cu is a naturally occurring copper peptide known for its regenerative and anti-aging effects. It plays a key role in wound healing, tissue repair, and skin rejuvenation by stimulating collagen, elastin, and glycosaminoglycan production. GHK-Cu also has antioxidant and anti-inflammatory properties, helping reduce oxidative stress and improve overall skin tone, firmness, and elasticity. Additionally, it may promote hair growth and support tissue repair throughout the body. It is widely used in skincare, haircare, and research for its ability to enhance cellular repair and youthful appearance.', 'c0a80121-0003-4e78-94f8-585d77059003', '1550.00', null, null, null, false, '99.00', null, null, null, 'Store at -20°C', null, 4, true, true, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780994548202-qqgsrqfuygn.png', null, '2026-06-07 14:07:28.269222+00', '2026-06-07 14:07:28.269222+00'), ('c67dee56-1de8-4b45-80b1-9a7652633129', 'LipoVela and LipoVela V', 'Lipovela is a lipotropic injectable blend commonly used to support fat metabolism, energy production, and overall wellness goals. It typically contains vitamins, amino acids, and metabolism-supporting compounds that may help the body break down and utilize fat more efficiently. Many users take Lipovela to support weight management, improve energy levels, and reduce feelings of fatigue during fitness or wellness programs. It is also popular for helping support liver function and promoting a more active metabolism.', 'all', '500.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 10, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781293632505-5nr858bzfx3.jpeg', null, '2026-06-10 11:22:13.604176+00', '2026-06-10 11:22:13.604176+00'), ('ce5ab9d8-473f-4562-bd7a-d59f0a65fab8', 'DSIP 15mg', 'DSIP (Delta Sleep-Inducing Peptide) is a research peptide that may help improve sleep quality, promote deeper restorative sleep, and support recovery from stress or physical strain. It is also studied for its potential to regulate stress hormones, reduce fatigue, and modulate pain perception. While primarily used in research, DSIP’s effects are linked to enhancing overall rest, recovery, and resilience.', 'c0a80121-0004-4e78-94f8-585d77059004', '1900.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 3, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781089765006-cbpd022weal.png', null, '2026-06-10 11:10:42.388402+00', '2026-06-10 11:10:42.388402+00'), ('d073b3bd-0ced-4e0c-9963-3120589a3b14', 'GHK-Cu 50mg', 'GHK-Cu is a naturally occurring copper peptide known for its regenerative and anti-aging effects. It plays a key role in wound healing, tissue repair, and skin rejuvenation by stimulating collagen, elastin, and glycosaminoglycan production. GHK-Cu also has antioxidant and anti-inflammatory properties, helping reduce oxidative stress and improve overall skin tone, firmness, and elasticity. Additionally, it may promote hair growth and support tissue repair throughout the body. It is widely used in skincare, haircare, and research for its ability to enhance cellular repair and youthful appearance.', 'all', '1400.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 6, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781337231770-aod6n1y5xx5.png', null, '2026-06-10 12:33:57.251474+00', '2026-06-10 12:33:57.251474+00'), ('d7702bf7-62f6-45d4-a8ed-397cbaecd96d', 'PINK HYALURONIC SKIN BOOSTER SERUM', 'Pink Hyaluronic Skin Booster Serum is a hydrating skincare product centered on hyaluronic acid, an ingredient that helps attract and retain moisture in the skin. It is commonly marketed to improve hydration, plumpness, and smoothness while giving the skin a more dewy, refreshed appearance. Exact results depend on the formula and concentration, but consistent use is generally aimed at supporting the skin barrier and reducing the look of dryness and fine lines.', 'all', '750.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 0, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1781293215378-bzkp38wu4ir.png', null, '2026-06-10 12:26:46.634381+00', '2026-06-10 12:26:46.634381+00'), ('e846ecdc-a9bf-45f5-a3c9-aad70103a5d0', 'GHK-Cu100mg + KPV10mg', 'GHKCU100+KPV10 is a powerful peptide blend designed to support skin renewal, repair, and overall skin health. GHK-Cu is known for promoting collagen production, improving skin elasticity, and helping reduce the appearance of fine lines and damaged skin. KPV is recognized for its calming and anti-inflammatory properties, which may help soothe redness and support faster skin recovery. Together, this combination is popular for beauty and wellness routines focused on rejuvenation, hydration, and healthier-looking skin.', 'c0a80121-0003-4e78-94f8-585d77059003', '1950.00', null, null, null, false, '99.00', '', '', '', 'Store at -20°C', null, 21, true, false, 'https://wdebbxcykvztyxfrrrxp.supabase.co/storage/v1/object/public/menu-images/1780998831283-k4n6qbkrzja.png', null, '2026-06-09 09:41:36.770919+00', '2026-06-09 09:41:36.770919+00'), ('f89d5a0d-6bdd-4761-a31e-e767d6a792ec', 'KLOW 80', 'KLOW is a multi-peptide research blend combining BPC‑157, TB‑500, GHK‑Cu, and KPV designed to support tissue repair, cellular regeneration, and inflammation control. It may promote soft tissue and gut healing, enhance cell migration and recovery, stimulate collagen production and skin rejuvenation, and provide anti-inflammatory and immune-modulating effects.

